mod solution;

fn main() {
    let cases = [
    (r#"[4,2,2,5,0,1,4]"#, r#"0,1,2,2,4,4,5"#),
    (r#"[5,0,5]"#, r#"0,5,5"#),
    (r#"
[5,0,5]
"#, r#"0,5,5"#),
    (r#"  
[4,2,2,5,0,1,4]
  "#, r#"0,1,2,2,4,4,5"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS counting-sort");
}
